tokens as (select root_id,id::text token from doc_ids union select root_id,r.pr1_number from public.pr1_requests r join g_pr1_requests g on r.id=g.id),
residual as (
select distinct t.root_id,'audit_logs'::text table_name,a.id,coalesce(a.document_type,'NULL') document_type,a.action detail
from public.audit_logs a join tokens t on coalesce(a.payload::text,'') like '%'||t.token||'%'
where not exists (select 1 from g_audit_logs g where g.id=a.id and g.root_id=t.root_id)
union all
select distinct t.root_id,'notifications',n.id,coalesce(n.document_type,'NULL'),n.type
from public.notifications n join tokens t on concat_ws(' ',n.action_url,n.title,n.body) like '%'||t.token||'%'
where not exists (select 1 from g_notifications g where g.id=n.id and g.root_id=t.root_id)
)
