 r join g_rfq_quote_attachments s on s.id=r.id where r.storage_path is not null union all select s.root_id,'compliance_documents'::text source,r.id row_id,r.storage_path path from public.compliance_documents r join g_compliance_documents s on s.id=r.id where r.storage_path is not null union all select s.root_id,'deliveries'::text source,r.id row_id,r.dr_document_path path from public.deliveries r join g_deliveries s on s.id=r.id where r.dr_document_path is not null),
report_roots as (
select r.id,r.pr1_number,r.created_at,r.purpose,r.status,r.requisitioner_name_snapshot,p.email,
(select jsonb_agg(jsonb_build_object('description',i.description,'remarks',i.remarks) order by i.item_order) from public.pr1_items i where i.pr1_id=r.id) items,
(select jsonb_object_agg(table_name,n) from (select table_name,count(*) n from scope s where s.root_id=r.id group by table_name) counts) footprint
from public.pr1_requests r join g_pr1_requests g on g.id=r.id left join public.profiles p on p.id=r.requisitioner_id
),
report_hashes as (select root_id,table_name,count(*) row_count,md5(string_agg(id::text,',' order by id)) id_hash,md5(string_agg(id::text||':'||row_hash,',' order by id)) content_hash from fingerprints group by root_id,table_name),
report_types as (
select s.root_id,s.table_name,c.id,c.document_type from (select 'notifications'::text table_name,id,document_type from public.notifications union all select 'audit_logs',id,document_type from public.audit_logs union all select 'approval_instances',id,document_type from public.approval_instances) c join scope s on s.table_name=c.table_name and s.id=c.id
where not exists (select 1 from doc_ids d join (select id,document_id from public.notifications union all select id,document_id from public.audit_logs union all select id,document_id from public.approval_instances) r on r.id=c.id and r.document_id=d.id where d.root_id=s.root_id and upper(c.document_type)=d.kind)
)
select jsonb_build_object(
'audited_at',statement_timestamp(),'project_ref','emddvbocupvufzvhcacz','read_only',true,
'roots',coalesce((select jsonb_agg(to_jsonb(r) order by created_at,id) from report_roots r),'[]'::jsonb),
'candidate_id_manifest',coalesce((select jsonb_agg(to_jsonb(r) order by root_id,table_name,id) from fingerprints r),'[]'::jsonb),
'candidate_fingerprints',coalesce((select jsonb_agg(to_jsonb(r) order by root_id,table_name) from report_hashes r),'[]'::jsonb),
'cross_boundary_edges',coalesce((select jsonb_agg(to_jsonb(r)) from cross_edges r),'[]'::jsonb),
'shared_rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select table_name,id,count(distinct root_id) roots from scope group by table_name,id having count(distinct root_id)>1) r),'[]'::jsonb),
'document_type_mismatches',coalesce((select jsonb_agg(to_jsonb(r)) from report_types r),'[]'::jsonb),
'residual_reference_hints',coalesce((select jsonb_agg(to_jsonb(r) order by root_id,table_name,id) from residual r),'[]'::jsonb),
'storage_paths_do_not_delete',coalesce((select jsonb_agg(to_jsonb(r) order by root_id,source,row_id) from paths r),'[]'::jsonb),
'independent_pr2_roots_do_not_delete',coalesce((select jsonb_agg(jsonb_build_object('id',id,'number',pr2_number,'created_at',created_at) order by created_at) from public.pr2_requests where pr1_id is null),'[]'::jsonb),
'next_pr1',public.next_pr1_sequence(2026),'next_pr2',public.next_pr2_sequence(2026),
'public_schema_columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'ordinal',ordinal_position) order by table_name,ordinal_position) from information_schema.columns where table_schema='public'),
'foreign_keys',(select jsonb_agg(jsonb_build_object('child_schema',nc.nspname,'child_table',cc.relname,'name',c.conname,'parent_schema',np.nspname,'parent_table',cp.relname,'definition',pg_get_constraintdef(c.oid)) order by nc.nspname,cc.relname,c.conname) from pg_constraint c join pg_class cc on cc.oid=c.conrelid join pg_namespace nc on nc.oid=cc.relnamespace join pg_class cp on cp.oid=c.confrelid join pg_namespace np on np.oid=cp.relnamespace where c.contype='f' and (nc.nspname='public' or np.nspname='public')),
'workflow_triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid)) order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and c.relname in ('pr1_requests','pr1_items','pr1_attachments','warehouse_validations','warehouse_validation_items','pr2_requests','pr2_items','pr2_item_attachments','pr2_requests_archive','pr2_items_archive','rfq_batches','rfq_suppliers','rfq_item_quotes','rfq_quote_attachments','supplier_item_selections','substitute_decisions','po_requests','po_items','po_receipts','compliance_documents','deliveries','delivery_status_history','grn_receipts','grn_items','approval_instances','approval_actions','notifications','audit_logs'))
) audit;



